	async function toggleFollow(type, uid, theiruid) {
		if (parseInt(uid,10)<=0||parseInt(theiruid,10)<=0) throw new Error('[[error:invalid-uid]]');
		if (uid===theiruid) throw new Error('[[error:you-cant-follow-yourself]]');
